if len(hand) and len(obj):
 ds=np.linalg.norm(hand[:,None,:]-obj[None,:,:],axis=2);ii,jj=np.unravel_index(np.argmin(ds),ds.shape);print('nearest',ds[ii,jj],hand[ii],obj[jj])
